import os,glob,re
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G)); print(G)

def f(g):
    h=len(g); w=len(g[0])
    rs=[2 if any(v%2==0 for v in row) else 1 for row in g]
    cs=[2 if any(g[i][j]%2==0 for i in range(h)) else 1 for j in range(w)]
    out=[]
    for i in range(h):
        for _ in range(rs[i]):
            row=[]
            for j in range(w):
                row += [g[i][j]]*cs[j]
            out.append(row)
    return out

print(f(G['Demo pair 1 input'])==G['Demo pair 1 output'])

def f2(g):
    h=len(g); w=len(g[0])
    c=g[h//2][w//2]
    rs=[1 if row[w//2]==c else 2 for row in g]
    cs=[1 if g[h//2][j]==c else 2 for j in range(w)]
    out=[]
    for i,row in enumerate(g):
        for _ in range(rs[i]):
            r=[]
            for j,v in enumerate(row): r+= [v]*cs[j]
            out.append(r)
    return out
for k in ['Demo pair 1 input','Demo pair 2 input']:
